import React, { useEffect, useMemo, useRef } from 'react';
import { useContexState } from '../hooks/context';

import api from '../services/api'

interface ConvertListParam {
    data: {
        id: number;
        number: number;
        name: string;
        phone: string;
        price: number;
        analyzed: number;
    }[]
};

interface ConvertListReturn {
    [key: string]: [{
        id: number;
        name: string;
        phone: string;
        price: number;
        analyzed: number;
    }]
};

interface Lines {
    firstCard: number;
    id: string;
};

function LoadPage(value: number | number = 0, func: { (): void } = () => { }) {
    const { listData, setlistData, perPage, getList, setGetList, setIsMountedApi, isMountedApi } = useContexState();

    const lines: Lines[] = [];
    setIsMountedApi(false);
    for (let i = 0; i < perPage; i++) {
        lines.push({
            firstCard: (i * 6) + value, id: String(i)
        });

    };
    setlistData([...lines]);
  //  isMounted.current = true;

}

export function useLoadPage() {
    const { listData, setlistData, perPage, getList, setGetList, setIsMountedApi, isMountedApi } = useContexState();
    const firstCard = listData[0]?.firstCard;
    const isMounted = useRef(false);

    function convertList({ data }: ConvertListParam) {
        return data.reduce((h: ConvertListReturn, card) => {
            const user = {
                id: card.id,
                name: card.name,
                phone: card.phone,
                price: card.price,
                analyzed: card.analyzed,
            };
            return Object.assign(h, {
                [card.number]: (h[card.number] || []).concat(user)
            });
        }, {});
    };

    function limiterNumber(number: number) {
        if (number + (perPage * 6) - 1 < 9999) {
            return number + (perPage * 6) - 1
        } else {
            return 9999
        }
    };

    async function fetchApi() {
        if (isMounted.current) {
            isMounted.current = false;
            await api.get("getCards", {
                params: {
                    firstNumber: firstCard,
                    lastNumber: limiterNumber(firstCard),
                }
            }
            ).then((responce) => {
                setIsMountedApi(true);
                console.log(JSON.stringify(responce.data));
                setGetList(convertList(responce));
            });
        };
    };

    useMemo(() => fetchApi(), [isMounted.current]);




    return { LoadPage };
};
